/**
 * The session-header trigger (conversation.session.header.actions, id
 * 'comfyui'): a labelled button that toggles the ComfyUI panel, plus the
 * connection reminder toast shown when the backend cannot reach ComfyUI.
 */
import { Fragment, createElement as h } from 'react'
import { panelStore, usePanelOpen } from './panel-store.ts'
import { ConnectionToast, probeConnection } from './connection.tsx'

export interface ComfyUITriggerProps {
  t: (key: string, ...rest: unknown[]) => string
}

/**
 * ComfyUI brand glyph (mono), inlined from @lobehub/icons-static-svg
 * (lobehub.com/icons). currentColor fill keeps it theme-aware.
 */
export function ComfyUIIcon(): ReturnType<typeof h> {
  return h('svg', {
    viewBox: '0 0 24 24',
    width: '1em', height: '1em',
    fill: 'currentColor', fillRule: 'evenodd',
    style: { flex: 'none', lineHeight: 1 },
    'aria-hidden': true,
  }, h('path', { d: 'M5.485 23.76c-.568 0-1.026-.207-1.325-.598-.307-.402-.387-.964-.22-1.54l.672-2.315a.605.605 0 00-.1-.536.622.622 0 00-.494-.243H2.085c-.568 0-1.026-.207-1.325-.598-.307-.403-.387-.964-.22-1.54l2.31-7.917.255-.87c.343-1.18 1.592-2.14 2.786-2.14h2.313c.276 0 .519-.18.595-.442l.764-2.633C9.906 1.208 11.155.249 12.35.249l4.945-.008h3.62c.568 0 1.027.206 1.325.597.307.402.387.964.22 1.54l-1.035 3.566c-.343 1.178-1.593 2.137-2.787 2.137l-4.956.01H11.37a.618.618 0 00-.594.441l-1.928 6.604a.605.605 0 00.1.537c.118.153.3.243.495.243l3.275-.006h3.61c.568 0 1.026.206 1.325.598.307.402.387.964.22 1.54l-1.036 3.565c-.342 1.179-1.592 2.138-2.786 2.138l-4.957.01h-3.61z' }),
  )
}

/** Header-action button toggling the ComfyUI panel. Opening it also fires a
 * backend connectivity probe: when ComfyUI is down, a reminder toast explains
 * why the panel stays empty instead of the click appearing to do nothing. */
export function ComfyUITrigger({ t }: ComfyUITriggerProps): ReturnType<typeof h> {
  const open = usePanelOpen()
  return h(Fragment, null,
    h('button', {
      className: 'dsc-trigger',
      title: t('panelTitle'),
      'aria-label': t('panelTitle'),
      'aria-pressed': open,
      onClick: () => {
        const opening = !panelStore.isOpen()
        panelStore.toggle()
        if (opening) void probeConnection()
      },
    },
      h('span', { className: 'dsc-trigger-glyph' }, h(ComfyUIIcon)),
      h('span', null, t('panelTitle')),
    ),
    h(ConnectionToast, { t }),
  )
}
